{
  "query": "change own password before expiry self-service",
  "reason": "Need the self-service steps for a user changing a password before it expires, which no provided article covers."
}

{
  "outcome": "resolved",
  "reply_to_user": "Hi Mei, you can change your own password from your laptop before it expires. Connect to the office network or VPN first, then press Ctrl+Alt+Delete on your keyboard and choose \"Change a password.\" Enter your current password, then your new one twice. The new password must be at least 14 characters and can't be a recent password you've used. If you get stuck or see an error, reply here and we'll help. Please don't send your password in a ticket or email.",
  "internal_note": "Ticket EVAL-fp-04, P4, simple how-to. lookup_user: Mei Chen (user_id 9) is active, not blocked, not locked, failed_login_count 0, must_change_password false, password last set 2026-09-11, VIP false. No reset or unlock was needed or requested. Searched KB: no article covers self-service password change before expiry. KB-002 covers forgotten passwords and KB-003 gives the Windows sign-in-screen change path and the 14-character/no-reuse rule, which I used for the reply. The Ctrl+Alt+Delete wording is standard Windows and not spelled out in the KB, so confidence is medium. FYI for the technician: the mailbox is at 99.4% of its 51200 MB quota (50890 MB used). That is unrelated to this ticket but may cause send/receive problems soon.",
  "kb_articles": [
    "KB-003",
    "KB-002"
  ],
  "confidence": "medium"
}
